import{_ as e,c as n,o as s,ag as t}from"./chunks/framework.KcKrU9KS.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"linux/Ubantu/Ubantu软件安装.md","filePath":"linux/Ubantu/Ubantu软件安装.md","lastUpdated":1773107605000}'),o={name:"linux/Ubantu/Ubantu软件安装.md"};function i(l,a,p,r,d,h){return s(),n("div",null,a[0]||(a[0]=[t(`<p>远程链接 ssh <a href="mailto:root@172.18.15.128" target="_blank" rel="noreferrer">root@172.18.15.128</a> ssh <a href="mailto:root@172.18.15.130" target="_blank" rel="noreferrer">root@172.18.15.130</a></p><h3 id="_1-更新源及软件升级" tabindex="-1">1. 更新源及软件升级 <a class="header-anchor" href="#_1-更新源及软件升级" aria-label="Permalink to &quot;1. 更新源及软件升级&quot;">​</a></h3><p>更改ubuntu源为清华源 sudo gedit /etc/apt/sources.list <a href="https://mirror.tuna.tsinghua.edu.cn/help/ubuntu/" target="_blank" rel="noreferrer">https://mirror.tuna.tsinghua.edu.cn/help/ubuntu/</a></p><pre><code>sudo apt update 更新系统
sudo apt upgrade 升级软件
</code></pre><h3 id="_2-安装搜狗输入法" tabindex="-1">2. 安装搜狗输入法 <a class="header-anchor" href="#_2-安装搜狗输入法" aria-label="Permalink to &quot;2. 安装搜狗输入法&quot;">​</a></h3><p>add the chinese language support 增加中文支持 install fcitx 安装fcitx *follow the sogou pinyin install instructions 根据指引安装 <a href="https://shurufa.sogou.com/linux/guide" target="_blank" rel="noreferrer">https://shurufa.sogou.com/linux/guide</a></p><h3 id="_3-安装必要应用软件" tabindex="-1">3. 安装必要应用软件 <a class="header-anchor" href="#_3-安装必要应用软件" aria-label="Permalink to &quot;3. 安装必要应用软件&quot;">​</a></h3><p>install VPN 安装VPN</p><p>install google-chrome 安装Chrome浏览器</p><p>install Feishu 安装飞书办公软件</p><p>install WPS 安装WPS办公套件</p><p>install code 安装VSCODE</p><p>install Xterminal 安装Xterminal</p><p>install Zed 安装Zed编辑器 <a href="https://zed.dev/download" target="_blank" rel="noreferrer">https://zed.dev/download</a></p><p>install wezterm [<a href="https://github.com/wezterm/wezterm/releases" target="_blank" rel="noreferrer">https://github.com/wezterm/wezterm/releases</a>] 配置文件, sudo gedit ~/.wezterm.lua</p><h3 id="_4-自动挂载硬盘" tabindex="-1">4. 自动挂载硬盘 <a class="header-anchor" href="#_4-自动挂载硬盘" aria-label="Permalink to &quot;4. 自动挂载硬盘&quot;">​</a></h3><p>点击左下角左应用程序（Win键）-&gt; 选择Disks -&gt; 找到所在的硬盘和分区 -&gt; 点击设置 -&gt; 修改挂载选项（Edit Mount Option）-&gt; 取消User Session Default 勾选</p><p>即可实现自动挂载</p><h3 id="_5-修改日历选项" tabindex="-1">5.修改日历选项 <a class="header-anchor" href="#_5-修改日历选项" aria-label="Permalink to &quot;5.修改日历选项&quot;">​</a></h3><p>使用</p><p>locale</p><p>查看当前设置的区域 执行</p><p>sudo gedit /usr/share/i18n/locales/zh_CN</p><p>打开设置，找到 “ first_weekday 2 ” 这一行，将2改成1，周日设置为每周的第一天</p><p>使用命令</p><p>sudo locale-gen</p><p>重新生成 locale 信息</p><h3 id="_6-安装firefox及创建桌面快捷方式" tabindex="-1">6.安装Firefox及创建桌面快捷方式 <a class="header-anchor" href="#_6-安装firefox及创建桌面快捷方式" aria-label="Permalink to &quot;6.安装Firefox及创建桌面快捷方式&quot;">​</a></h3><p>先下载firefox，：<a href="https://www.mozilla.org/en-US/firefox/download/thanks/" target="_blank" rel="noreferrer">https://www.mozilla.org/en-US/firefox/download/thanks/</a> 然后解压到home目录，并在icon文件夹中添加图标：添加图标：<a href="https://www.flaticon.com/free-icon/firefox_5968822" target="_blank" rel="noreferrer">https://www.flaticon.com/free-icon/firefox_5968822</a></p><p>创建快捷方式到桌面，创建文件： sudo gedit /usr/share/applications/firefox.desktop 然后放入一下信息（如果路径不一致自行修改）</p><p>[Desktop Entry] Encoding=UTF-8 Name=Firefox Comment=Firefox Exec=/home/andy/firefox/firefox Icon=/home/andy/firefox/icons/firefox.png Terminal=false# 如果没有给自己账户root权限就需要这里设为true来启动终端输入密码 StartupNotify=true Type=Application Categories=Application;Development;</p><p>最后的最后，重启下机器。</p><h3 id="_7-安装nvm-下载nodejs" tabindex="-1">7.安装nvm 下载nodeJS <a class="header-anchor" href="#_7-安装nvm-下载nodejs" aria-label="Permalink to &quot;7.安装nvm 下载nodeJS&quot;">​</a></h3><p><a href="https://locahost:3002/" target="_blank" rel="noreferrer">https://locahost:3002/</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt install curl</span></span></code></pre></div><h5 id="_1-nvm-是一个跨平台的-node-js-版本管理器。" tabindex="-1">1.&quot;nvm&quot; 是一个跨平台的 Node.js 版本管理器。 <a class="header-anchor" href="#_1-nvm-是一个跨平台的-node-js-版本管理器。" aria-label="Permalink to &quot;1.&quot;nvm&quot; 是一个跨平台的 Node.js 版本管理器。&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download and install nvm:</span></span>
<span class="line"><span>curl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.3/install.sh | bash</span></span></code></pre></div><h5 id="_2-无需重启-shell" tabindex="-1">2.无需重启 shell <a class="header-anchor" href="#_2-无需重启-shell" aria-label="Permalink to &quot;2.无需重启 shell&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># in lieu of restarting the shell</span></span>
<span class="line"><span>\\. &quot;$HOME/.nvm/nvm.sh&quot;</span></span>
<span class="line"><span>nvm -v             # Should print &quot;0.40.3&quot;</span></span></code></pre></div><h5 id="_3-下载node-js" tabindex="-1">3.下载Node.js <a class="header-anchor" href="#_3-下载node-js" aria-label="Permalink to &quot;3.下载Node.js&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download and install Node.js:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>安装LTS版</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nvm install --lts</span></span></code></pre></div><h5 id="_4-查看node-js版本" tabindex="-1">4.查看Node.js版本 <a class="header-anchor" href="#_4-查看node-js版本" aria-label="Permalink to &quot;4.查看Node.js版本&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> Verify the Node.js version:</span></span>
<span class="line"><span>node -v # Should print &quot;v22.15.0&quot;.</span></span></code></pre></div><h5 id="_5-nvm当前的版本" tabindex="-1">5.nvm当前的版本 <a class="header-anchor" href="#_5-nvm当前的版本" aria-label="Permalink to &quot;5.nvm当前的版本&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm current # Should print &quot;v22.15.0&quot;.</span></span>
<span class="line"><span>6.npm的版本# Verify npm version:</span></span>
<span class="line"><span>npm -v # Should print &quot;10.9.2&quot;.</span></span></code></pre></div><h5 id="_7-nvm使用当前版本" tabindex="-1">7.nvm使用当前版本 <a class="header-anchor" href="#_7-nvm使用当前版本" aria-label="Permalink to &quot;7.nvm使用当前版本&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nvm use 22.15.0</span></span></code></pre></div><h5 id="_8-node所下目录" tabindex="-1">8.node所下目录 <a class="header-anchor" href="#_8-node所下目录" aria-label="Permalink to &quot;8.node所下目录&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>which node  </span></span>
<span class="line"><span>/root/.nvm/versions/node/v22.15.0/bin/node</span></span></code></pre></div><h5 id="_9-nvm-所下目录" tabindex="-1">9.nvm 所下目录 <a class="header-anchor" href="#_9-nvm-所下目录" aria-label="Permalink to &quot;9.nvm 所下目录&quot;">​</a></h5><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>which nvm </span></span>
<span class="line"><span>/root/.nvm/versions/node/v22.15.0/bin:</span></span>
<span class="line"><span>/usr/local/sbin:</span></span></code></pre></div>`,51)]))}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
